/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: MotionPreviewPanel
 * Internal
 *   Types: Outcome
 * @end-catalog */

import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useRef, useState } from 'react';

import { ApiError } from '../../api/client';
import { useAdminAccess, useAdminText } from './AdminAccess';
import styles from './adminStyles';
import { motionPreviewApi, type MotionPreviewStatus } from './motionPreviewApi';

type Outcome = 'uploaded' | 'removed' | 'reconciled' | 'cleanupPending' | 'error';

/**
 * Lets an administrator attach, replace, remove, or reconcile the muted motion preview of one
 * Video MediaTrack. It renders nothing while the feature is disabled or for an Audio MediaTrack.
 */
export function MotionPreviewPanel({ id }: { id: string }) {
  const t = useAdminText();
  const access = useAdminAccess();
  const client = useQueryClient();
  const file = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  const [outcome, setOutcome] = useState<Outcome | null>(null);
  const queryKey = ['admin-motion-preview', access.viewerId, access.epoch, access.generation, id];
  const status = useQuery({
    queryKey,
    queryFn: ({ signal }) => motionPreviewApi.status(id, undefined, signal),
    retry: false,
    gcTime: 0
  });

  if (status.isError && status.error instanceof ApiError && status.error.status === 404) return null;
  const data: MotionPreviewStatus | undefined = status.data;
  if (data && !data.eligible && !data.active && !data.pending && !data.cleanup) return null;

  const run = async (work: () => Promise<{ cleanupPending: boolean }>, done: Outcome) => {
    setBusy(true);
    setOutcome(null);
    try {
      const result = await work();
      setOutcome(result.cleanupPending ? 'cleanupPending' : done);
    } catch {
      setOutcome('error');
    } finally {
      setBusy(false);
      await client.invalidateQueries({ queryKey });
    }
  };

  const upload = () => {
    const selected = file.current?.files?.[0];
    if (!selected || !data) return;
    void run(() => motionPreviewApi.upload(id, selected, data), 'uploaded').then(() => {
      if (file.current) file.current.value = '';
    });
  };

  const needsAttention = Boolean(data?.pending || data?.cleanup);
  return (
    <section className={styles.panel} aria-labelledby="motion-preview-title">
      <header className={styles.sectionHeader}><h2 id="motion-preview-title">{t('motionPreview.title')}</h2></header>
      <p className={styles.muted}>{t('motionPreview.copy')}</p>
      {status.isPending && <p role="status">{t('common.loading')}</p>}
      {status.isError && !(status.error instanceof ApiError && status.error.status === 404) && (
        <p role="alert" className={styles.notice}>{t('common.error')}</p>
      )}
      {data && <>
        {data.active ? (
          <p>
            {t('motionPreview.current', {
              seconds: (data.active.durationMs / 1000).toFixed(1),
              width: data.active.width,
              height: data.active.height
            })}
            {!data.active.current && <> {t('motionPreview.outdated')}</>}
          </p>
        ) : <p>{t('motionPreview.none')}</p>}
        {needsAttention && <p role="status">{t('motionPreview.attention')}</p>}
        <label className={styles.field}>
          {t('motionPreview.file')}
          <input
            accept="video/mp4"
            className={styles.input}
            disabled={busy || !data.eligible}
            ref={file}
            type="file"
          />
        </label>
        <div className={styles.actions}>
          <button
            className={`${styles.button} ${styles.primary}`}
            disabled={busy || !data.eligible || !data.sourceToken || Boolean(data.pending?.leaseActive)}
            onClick={upload}
            type="button"
          >
            {t('motionPreview.upload')}
          </button>
          {data.active && (
            <button
              className={styles.button}
              disabled={busy || needsAttention}
              onClick={() => { void run(() => motionPreviewApi.remove(id, data.revision), 'removed'); }}
              type="button"
            >
              {t('motionPreview.remove')}
            </button>
          )}
          {needsAttention && (
            <button
              className={styles.button}
              disabled={busy || Boolean(data.pending?.leaseActive)}
              onClick={() => { void run(() => motionPreviewApi.reconcile(id), 'reconciled'); }}
              type="button"
            >
              {t('motionPreview.reconcile')}
            </button>
          )}
        </div>
      </>}
      {outcome && (
        <p role={outcome === 'error' ? 'alert' : 'status'} className={outcome === 'error' ? styles.notice : undefined}>
          {t(`motionPreview.${outcome === 'cleanupPending' ? 'cleanup_pending' : outcome}`)}
        </p>
      )}
    </section>
  );
}
